    @Override
    @Transactional
    public void run(String... args) throws Exception {
        if (!seedEnabled) {
            log.info("App seed is disabled (app.seed.enabled=false). Skipping InitData.");
            return;
        }

        seededEntityIds.clear();
        log.info("Running InitData (Sync-Seed Mode: dong bo du lieu mau, giu nguyen du lieu tu tao)...");
        entityManager.setFlushMode(FlushModeType.COMMIT);

        seedAllUsersAndAddresses();
        entityManager.flush();

        seedAllCategories();
        entityManager.flush();

        seedAllProducts();
        entityManager.flush();

        seedAllVariantsBatch1();
        seedAllVariantsBatch2();
        seedAllVariantsBatch3();
        seedAllVariantsBatch4();
        entityManager.flush();

        seedAllProductImages();
        entityManager.flush();

        seedAllPaymentMethodsAndOffers();
        entityManager.flush();

        seedAllOrdersBatch1();
        seedAllOrdersBatch2();
        entityManager.flush();

        seedAllOrderItemsBatch1();
        seedAllOrderItemsBatch2();
        seedAllOrderItemsBatch3();
        entityManager.flush();

        seedAllPaymentTransactionsBatch1();
        seedAllPaymentTransactionsBatch2();
        entityManager.flush();

        seedAllReturnsAndReviews();
        entityManager.flush();

        seedRealtimeNotificationsAndChat();
        entityManager.flush();

        auditUnseededRecordsMissingFields();
        log.info("InitData completed successfully.");
    }

