    private User seedUser(String username, String passwordHash, String fullname, Gender gender,
                          LocalDate dateOfBirth, String phone, String email, RoleUser role, StatusUser status) {
        User u = userRepository.findByUsername(username)
                .orElse(new User());

        u.setUsername(username);
        if (u.getPasswordHash() == null) {
            u.setPasswordHash(passwordHash);
        }
        u.setFullname(fullname);
        u.setGender(gender);
        u.setDateOfBirth(dateOfBirth);
        u.setPhone(phone);
        u.setEmail(email);
        u.setRole(role);
        u.setStatus(status);

        User saved = userRepository.save(u);
        trackSeeded(saved, saved.getId());
        return saved;
    }

    private UserAddress seedUserAddress(User user, String fullAddress, String provinceName,
                                        String wardName, AddressType addressType, boolean isDefault) {
        UserAddress a = userAddressRepository.findFirstByUserIdAndFullAddress(user.getId(), fullAddress)
                .orElse(new UserAddress());

        a.setUser(user);
        a.setFullAddress(fullAddress);
        a.setProvinceName(provinceName);
        a.setWardName(wardName);
        a.setAddressType(addressType);
        a.setIsDefault(isDefault);

        UserAddress saved = userAddressRepository.save(a);
        trackSeeded(saved, saved.getId());
        return saved;
    }

